window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-4280294ddd47abc4"]={"versions": [{"id": "FIG-4280294ddd47abc4", "releases": ["R1.3.0", "R17-10_R1.2.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout eines SOME/IP-Serialisierungs-Tags (Tag-basiertes Member-Encoding) im Kontext des AUTOSAR SOME/IP-Protokolls. Das Diagramm spezifiziert die Bitfeldbelegung innerhalb des zweibändigen Tag-Headers sowie die Anordnung nachfolgender optionaler Längenfelder und Nutzdaten im serialisierten Bytestrom.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Byte n (Tag High Byte)</strong>:\n<ul class=\"fig-list\"><li><code>reserved</code>: 1 Bit (Bit 7, MSB).\n</li><li><code>Wire Type</code>: 3 Bit (Bits 6–4).\n</li><li><code>Data ID (Higher Sig. Part)</code>: 4 Bit (Bits 3–0).\n</li></ul>\n</li><li><strong>Byte n + 1 (Tag Low Byte)</strong>:\n<ul class=\"fig-list\"><li><code>Data ID (Lower Sig. Part)</code>: 8 Bit (Bits 7–0).\n</li></ul>\n</li><li><strong>Byte n + 2 ... (Optionales Längenfeld)</strong>:\n<ul class=\"fig-list\"><li><code>Length Field (8/16/32 bit)</code>: Variabel breites Längenfeld mit Bitindizes 7/15/31 bis 0, geklammert durch eckige Begrenzungssymbole.\n</li></ul>\n</li><li><strong>Folgende Bytes</strong>:\n<ul class=\"fig-list\"><li><code>Member Data ...</code>: Serialisierte Nutzdaten des jeweiligen Strukturelements oder Methodenarguments.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Deserialisierer liest <code>Byte n</code> und <code>Byte n + 1</code> als vollständigen 16-Bit-Tag.\n</li><li>Extraktion des Wire Types aus Bits 6–4 von Byte n zur Bestimmung des Datentyps bzw. des Serialisierungsformats.\n</li><li>Rekonstruktion der 12-Bit-Data-ID aus dem höherwertigen 4-Bit-Teil (Byte n, Bits 3–0) und dem niederwertigen 8-Bit-Teil (Byte n + 1, Bits 7–0) zur Identifikation des Strukturelements oder Methodenarguments.\n</li><li>Bei Wire-Typen, die ein Längenfeld erfordern, Auswertung des <code>Length Field (8/16/32 bit)</code> ab <code>Byte n + 2</code>.\n</li><li>Einlesen bzw. Dekodieren der eigentlichen Elementdaten (<code>Member Data ...</code>) gemäß der zuvor ermittelten Länge oder Typdefinition.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Ein Tag besitzt eine feste Gesamtlänge von 2 Bytes (16 Bit).\n</li><li>Das höchstwertige Bit (Bit 7 in Byte n) ist reserviert und muss entsprechend Spezifikation behandelt werden.\n</li><li>Die Data ID ist 12 Bit breit, aufgeteilt in ein oberes 4-Bit-Nibble und ein unteres 8-Bit-Byte.\n</li><li>Data IDs müssen innerhalb der direkten Member einer Struktur oder Argumente einer Methode eindeutig sein.\n</li><li>Die Auswertung des <code>Length Field</code> ist abhängig vom deklarierten Wire Type (zulässige Längen: 8, 16 oder 32 Bit). Wire-Typen für statische Basistypen tragen kein Längenfeld.\n</li></ul>"}, {"id": "FIG-28d11ef5f0971432", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout eines SOME/IP-Serialisierungs-Tags (Tag-basiertes Member-Encoding) im Kontext des AUTOSAR SOME/IP-Protokolls. Das Diagramm spezifiziert die Bitfeldbelegung innerhalb des zweibändigen Tag-Headers sowie die Anordnung nachfolgender optionaler Längenfelder und Nutzdaten im serialisierten Bytestrom.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Byte n (Tag High Byte)</strong>:\n<ul class=\"fig-list\"><li><code>reserved</code>: 1 Bit (Bit 7, MSB).\n</li><li><code>Wire Type</code>: 3 Bit (Bits 6–4).\n</li><li><code>Data ID (Higher Sig. Part)</code>: 4 Bit (Bits 3–0).\n</li></ul>\n</li><li><strong>Byte n + 1 (Tag Low Byte)</strong>:\n<ul class=\"fig-list\"><li><code>Data ID (Lower Sig. Part)</code>: 8 Bit (Bits 7–0).\n</li></ul>\n</li><li><strong>Byte n + 2 ... (Optionales Längenfeld)</strong>:\n<ul class=\"fig-list\"><li><code>Length Field (8/16/32 bit)</code>: Variabel breites Längenfeld mit Bitindizes 7/15/31 bis 0, geklammert durch eckige Begrenzungssymbole.\n</li></ul>\n</li><li><strong>Folgende Bytes</strong>:\n<ul class=\"fig-list\"><li><code>Member Data ...</code>: Serialisierte Nutzdaten des jeweiligen Strukturelements oder Methodenarguments.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Deserialisierer liest <code>Byte n</code> und <code>Byte n + 1</code> als vollständigen 16-Bit-Tag.\n</li><li>Extraktion des Wire Types aus Bits 6–4 von Byte n zur Bestimmung des Datentyps bzw. des Serialisierungsformats.\n</li><li>Rekonstruktion der 12-Bit-Data-ID aus dem höherwertigen 4-Bit-Teil (Byte n, Bits 3–0) und dem niederwertigen 8-Bit-Teil (Byte n + 1, Bits 7–0) zur Identifikation des Strukturelements oder Methodenarguments.\n</li><li>Bei Wire-Typen, die ein Längenfeld erfordern, Auswertung des <code>Length Field (8/16/32 bit)</code> ab <code>Byte n + 2</code>.\n</li><li>Einlesen bzw. Dekodieren der eigentlichen Elementdaten (<code>Member Data ...</code>) gemäß der zuvor ermittelten Länge oder Typdefinition.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Ein Tag besitzt eine feste Gesamtlänge von 2 Bytes (16 Bit).\n</li><li>Das höchstwertige Bit (Bit 7 in Byte n) ist reserviert und muss entsprechend Spezifikation behandelt werden.\n</li><li>Die Data ID ist 12 Bit breit, aufgeteilt in ein oberes 4-Bit-Nibble und ein unteres 8-Bit-Byte.\n</li><li>Data IDs müssen innerhalb der direkten Member einer Struktur oder Argumente einer Methode eindeutig sein.\n</li><li>Die Auswertung des <code>Length Field</code> ist abhängig vom deklarierten Wire Type (zulässige Längen: 8, 16 oder 32 Bit). Wire-Typen für statische Basistypen tragen kein Längenfeld.\n</li></ul>"}, {"id": "FIG-c4ca3750c724444d", "releases": ["R17-03_R1.1.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout eines SOME/IP-Serialisierungs-Tags (Tag-basiertes Member-Encoding) im Kontext des AUTOSAR SOME/IP-Protokolls. Das Diagramm spezifiziert die Bitfeldbelegung innerhalb des zweibändigen Tag-Headers sowie die Anordnung nachfolgender optionaler Längenfelder und Nutzdaten im serialisierten Bytestrom.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Byte n (Tag High Byte)</strong>:\n<ul class=\"fig-list\"><li><code>reserved</code>: 1 Bit (Bit 7, MSB).\n</li><li><code>Wire Type</code>: 3 Bit (Bits 6–4).\n</li><li><code>Data ID (Higher Sig. Part)</code>: 4 Bit (Bits 3–0).\n</li></ul>\n</li><li><strong>Byte n + 1 (Tag Low Byte)</strong>:\n<ul class=\"fig-list\"><li><code>Data ID (Lower Sig. Part)</code>: 8 Bit (Bits 7–0).\n</li></ul>\n</li><li><strong>Byte n + 2 ... (Optionales Längenfeld)</strong>:\n<ul class=\"fig-list\"><li><code>Length Field (8/16/32 bit)</code>: Variabel breites Längenfeld mit Bitindizes 7/15/31 bis 0, geklammert durch eckige Begrenzungssymbole.\n</li></ul>\n</li><li><strong>Folgende Bytes</strong>:\n<ul class=\"fig-list\"><li><code>Member Data ...</code>: Serialisierte Nutzdaten des jeweiligen Strukturelements oder Methodenarguments.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Deserialisierer liest <code>Byte n</code> und <code>Byte n + 1</code> als vollständigen 16-Bit-Tag.\n</li><li>Extraktion des Wire Types aus Bits 6–4 von Byte n zur Bestimmung des Datentyps bzw. des Serialisierungsformats.\n</li><li>Rekonstruktion der 12-Bit-Data-ID aus dem höherwertigen 4-Bit-Teil (Byte n, Bits 3–0) und dem niederwertigen 8-Bit-Teil (Byte n + 1, Bits 7–0) zur Identifikation des Strukturelements oder Methodenarguments.\n</li><li>Bei Wire-Typen, die ein Längenfeld erfordern, Auswertung des <code>Length Field (8/16/32 bit)</code> ab <code>Byte n + 2</code>.\n</li><li>Einlesen bzw. Dekodieren der eigentlichen Elementdaten (<code>Member Data ...</code>) gemäß der zuvor ermittelten Länge oder Typdefinition.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Ein Tag besitzt eine feste Gesamtlänge von 2 Bytes (16 Bit).\n</li><li>Das höchstwertige Bit (Bit 7 in Byte n) ist reserviert und muss entsprechend Spezifikation behandelt werden.\n</li><li>Die Data ID ist 12 Bit breit, aufgeteilt in ein oberes 4-Bit-Nibble und ein unteres 8-Bit-Byte.\n</li><li>Data IDs müssen innerhalb der direkten Member einer Struktur oder Argumente einer Methode eindeutig sein.\n</li><li>Die Auswertung des <code>Length Field</code> ist abhängig vom deklarierten Wire Type (zulässige Längen: 8, 16 oder 32 Bit). Wire-Typen für statische Basistypen tragen kein Längenfeld.\n</li></ul>"}, {"id": "FIG-a70d29a84153ea3b", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout eines SOME/IP-Serialisierungs-Tags (Tag-basiertes Member-Encoding) im Kontext des AUTOSAR SOME/IP-Protokolls. Das Diagramm spezifiziert die Bitfeldbelegung innerhalb des zweibändigen Tag-Headers sowie die Anordnung nachfolgender optionaler Längenfelder und Nutzdaten im serialisierten Bytestrom.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Byte n (Tag High Byte)</strong>:\n<ul class=\"fig-list\"><li><code>reserved</code>: 1 Bit (Bit 7, MSB).\n</li><li><code>Wire Type</code>: 3 Bit (Bits 6–4).\n</li><li><code>Data ID (Higher Sig. Part)</code>: 4 Bit (Bits 3–0).\n</li></ul>\n</li><li><strong>Byte n + 1 (Tag Low Byte)</strong>:\n<ul class=\"fig-list\"><li><code>Data ID (Lower Sig. Part)</code>: 8 Bit (Bits 7–0).\n</li></ul>\n</li><li><strong>Byte n + 2 ... (Optionales Längenfeld)</strong>:\n<ul class=\"fig-list\"><li><code>Length Field (8/16/32 bit)</code>: Variabel breites Längenfeld mit Bitindizes 7/15/31 bis 0, geklammert durch eckige Begrenzungssymbole.\n</li></ul>\n</li><li><strong>Folgende Bytes</strong>:\n<ul class=\"fig-list\"><li><code>Member Data ...</code>: Serialisierte Nutzdaten des jeweiligen Strukturelements oder Methodenarguments.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Deserialisierer liest <code>Byte n</code> und <code>Byte n + 1</code> als vollständigen 16-Bit-Tag.\n</li><li>Extraktion des Wire Types aus Bits 6–4 von Byte n zur Bestimmung des Datentyps bzw. des Serialisierungsformats.\n</li><li>Rekonstruktion der 12-Bit-Data-ID aus dem höherwertigen 4-Bit-Teil (Byte n, Bits 3–0) und dem niederwertigen 8-Bit-Teil (Byte n + 1, Bits 7–0) zur Identifikation des Strukturelements oder Methodenarguments.\n</li><li>Bei Wire-Typen, die ein Längenfeld erfordern, Auswertung des <code>Length Field (8/16/32 bit)</code> ab <code>Byte n + 2</code>.\n</li><li>Einlesen bzw. Dekodieren der eigentlichen Elementdaten (<code>Member Data ...</code>) gemäß der zuvor ermittelten Länge oder Typdefinition.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Ein Tag besitzt eine feste Gesamtlänge von 2 Bytes (16 Bit).\n</li><li>Das höchstwertige Bit (Bit 7 in Byte n) ist reserviert und muss entsprechend Spezifikation behandelt werden.\n</li><li>Die Data ID ist 12 Bit breit, aufgeteilt in ein oberes 4-Bit-Nibble und ein unteres 8-Bit-Byte.\n</li><li>Data IDs müssen innerhalb der direkten Member einer Struktur oder Argumente einer Methode eindeutig sein.\n</li><li>Die Auswertung des <code>Length Field</code> ist abhängig vom deklarierten Wire Type (zulässige Längen: 8, 16 oder 32 Bit). Wire-Typen für statische Basistypen tragen kein Längenfeld.\n</li></ul>"}, {"id": "FIG-f4cb85f548688db4", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Bit- und Byte-Layout eines SOME/IP-Serialisierungs-Tags (Tag-basiertes Member-Encoding) im Kontext des AUTOSAR SOME/IP-Protokolls. Das Diagramm spezifiziert die Bitfeldbelegung innerhalb des zweibändigen Tag-Headers sowie die Anordnung nachfolgender optionaler Längenfelder und Nutzdaten im serialisierten Bytestrom.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Byte n (Tag High Byte)</strong>:\n<ul class=\"fig-list\"><li><code>reserved</code>: 1 Bit (Bit 7, MSB).\n</li><li><code>Wire Type</code>: 3 Bit (Bits 6–4).\n</li><li><code>Data ID (Higher Sig. Part)</code>: 4 Bit (Bits 3–0).\n</li></ul>\n</li><li><strong>Byte n + 1 (Tag Low Byte)</strong>:\n<ul class=\"fig-list\"><li><code>Data ID (Lower Sig. Part)</code>: 8 Bit (Bits 7–0).\n</li></ul>\n</li><li><strong>Byte n + 2 ... (Optionales Längenfeld)</strong>:\n<ul class=\"fig-list\"><li><code>Length Field (8/16/32 bit)</code>: Variabel breites Längenfeld mit Bitindizes 7/15/31 bis 0, geklammert durch eckige Begrenzungssymbole.\n</li></ul>\n</li><li><strong>Folgende Bytes</strong>:\n<ul class=\"fig-list\"><li><code>Member Data ...</code>: Serialisierte Nutzdaten des jeweiligen Strukturelements oder Methodenarguments.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Deserialisierer liest <code>Byte n</code> und <code>Byte n + 1</code> als vollständigen 16-Bit-Tag.\n</li><li>Extraktion des Wire Types aus Bits 6–4 von Byte n zur Bestimmung des Datentyps bzw. des Serialisierungsformats.\n</li><li>Rekonstruktion der 12-Bit-Data-ID aus dem höherwertigen 4-Bit-Teil (Byte n, Bits 3–0) und dem niederwertigen 8-Bit-Teil (Byte n + 1, Bits 7–0) zur Identifikation des Strukturelements oder Methodenarguments.\n</li><li>Bei Wire-Typen, die ein Längenfeld erfordern, Auswertung des <code>Length Field (8/16/32 bit)</code> ab <code>Byte n + 2</code>.\n</li><li>Einlesen bzw. Dekodieren der eigentlichen Elementdaten (<code>Member Data ...</code>) gemäß der zuvor ermittelten Länge oder Typdefinition.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Ein Tag besitzt eine feste Gesamtlänge von 2 Bytes (16 Bit).\n</li><li>Das höchstwertige Bit (Bit 7 in Byte n) ist reserviert und muss entsprechend Spezifikation behandelt werden.\n</li><li>Die Data ID ist 12 Bit breit, aufgeteilt in ein oberes 4-Bit-Nibble und ein unteres 8-Bit-Byte.\n</li><li>Data IDs müssen innerhalb der direkten Member einer Struktur oder Argumente einer Methode eindeutig sein.\n</li><li>Die Auswertung des <code>Length Field</code> ist abhängig vom deklarierten Wire Type (zulässige Längen: 8, 16 oder 32 Bit). Wire-Typen für statische Basistypen tragen kein Längenfeld.\n</li></ul>"}], "trans": [{"from": "FIG-4280294ddd47abc4", "to": "FIG-28d11ef5f0971432", "fr": "R1.3.0", "tr": "R1.5.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-28d11ef5f0971432", "to": "FIG-c4ca3750c724444d", "fr": "R1.5.1", "tr": "R17-03_R1.1.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-c4ca3750c724444d", "to": "FIG-4280294ddd47abc4", "fr": "R17-03_R1.1.0", "tr": "R17-10_R1.2.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-4280294ddd47abc4", "to": "FIG-a70d29a84153ea3b", "fr": "R17-10_R1.2.0", "tr": "R18-03_R1.4.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-a70d29a84153ea3b", "to": "FIG-28d11ef5f0971432", "fr": "R18-03_R1.4.0", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-28d11ef5f0971432", "to": "FIG-f4cb85f548688db4", "fr": "R19-03", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
